package com.trendradar.app;
import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.view.*;
import android.widget.*;
import android.text.InputType;
import org.json.*;
import java.util.*;
public class MainActivity extends Activity {
 LinearLayout root; String category="Todos"; boolean busy=false; int visibleLimit=20;
 final int bg=0xff101820,green=0xff75dab3,light=0xffedf1f0;
 String[] categories={"Todos","Productos","Innovaciones","Servicios","Empresas","IPO","Cuba"};
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},1);RadarWorker.schedule(this);openIntent(getIntent());}
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);openIntent(i);}
 void openIntent(Intent i){String id=i==null?null:i.getStringExtra("finding_id");if(id!=null)try{JSONArray a=Store.feed(this).getJSONArray("items");for(int x=0;x<a.length();x++){JSONObject o=a.getJSONObject(x);if(id.equals(o.optString("id"))){detail(o);return;}}}catch(Exception ignored){}home();}
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5);}
 TextView text(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(light);v.setPadding(0,dp(6),0,dp(6));return v;}
 void start(String title){ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(16),dp(12),dp(16),dp(24));root.setBackgroundColor(bg);scroll.addView(root);setContentView(scroll);TextView t=text(title,26);t.setTextColor(green);root.addView(t);}
 GradientDrawable round(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 LinearLayout panel(){LinearLayout p=new LinearLayout(this);p.setOrientation(1);p.setPadding(dp(14),dp(12),dp(14),dp(12));p.setBackground(round(0xff1b2933,20));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,dp(12));root.addView(p,lp);return p;}
 TextView sub(String s,int size,int color){TextView t=text(s,size);t.setTextColor(color);return t;}
 TextView strong(String s,int size){TextView t=text(s,size);t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
 void label(String s){root.addView(text(s,15));}
 void section(String title,String content){LinearLayout p=panel();p.addView(sub(title,13,green));p.addView(text(content,16));}
 ImageView cover(JSONObject item,int height){ImageView im=new ImageView(this);im.setScaleType(ImageView.ScaleType.CENTER_CROP);im.setBackground(round(0xff23323c,14));im.setClipToOutline(true);im.setLayoutParams(new LinearLayout.LayoutParams(-1,dp(height)));im.setContentDescription("Imagen de "+item.optString("name"));RadarImages.show(this,im,item);return im;}
 void finding(JSONObject o){LinearLayout p=panel();p.addView(cover(o,176));String cat=o.optString("category");p.addView(sub(RadarImages.symbol(cat)+"  "+cat+"  ·  "+o.optString("country")+"  ·  "+o.optString("date"),12,RadarImages.accent(cat)));p.addView(strong(o.optString("name","Hallazgo"),19));TextView desc=text(o.optString("summary"),14);desc.setMaxLines(3);desc.setEllipsize(android.text.TextUtils.TruncateAt.END);p.addView(desc);p.addView(sub("Explorar oportunidad  →",14,green));p.setOnClickListener(v->detail(o));p.setFocusable(true);}
 void filters(JSONArray a){String[] names={"Productos","Innovaciones","Servicios","Empresas","IPO","Cuba"};for(int j=0;j<names.length;j+=2){LinearLayout row=new LinearLayout(this);row.setOrientation(0);root.addView(row);for(int k=j;k<j+2;k++){String name=names[k];int count=0;for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&name.equalsIgnoreCase(o.optString("category")))count++;}LinearLayout tile=new LinearLayout(this);tile.setOrientation(1);tile.setPadding(dp(12),dp(11),dp(12),dp(10));tile.setBackground(round(category.equals(name)?0xff304b49:0xff1b2933,16));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(k==j?0:dp(6),0,k==j?dp(6):0,dp(10));row.addView(tile,lp);tile.addView(sub(RadarImages.symbol(name)+"   "+count,22,RadarImages.accent(name)));tile.addView(strong(name,15));tile.setOnClickListener(v->{category=name;visibleLimit=20;home();});}}}

 void button(String s,Runnable fn){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(light);b.setBackground(round(0xff29413f,14));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(48));lp.setMargins(0,dp(3),0,dp(7));root.addView(b,lp);b.setOnClickListener(v->fn.run());}
 EditText input(String title,String val,boolean number){label(title);EditText e=new EditText(this);e.setTextColor(light);e.setText(val);if(number)e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);root.addView(e);return e;}
 void message(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 void home(){start("◉ TrendRadar");LinearLayout hero=panel();hero.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff24453f,0xff1b2933}){{setCornerRadius(dp(20));}});hero.addView(sub("INTELIGENCIA GLOBAL",12,green));hero.addView(strong("Descubre lo que viene",24));hero.addView(text("Productos, empresas y servicios emergentes en un solo lugar.",15));long last=Store.prefs(this).getLong("last",0);hero.addView(sub(last==0?"Aún sin sincronizar":"Actualizado · "+new java.text.SimpleDateFormat("dd MMM · HH:mm",Locale.getDefault()).format(new java.util.Date(last)),12,0xffb7c9c4));button("↻  Actualizar hallazgos",()->refresh());button("⚙  Ajustes y conexión",()->settings());
 String err=Store.prefs(this).getString("error","");if(!err.isEmpty())label("Estado: "+err);
 try{JSONArray a=Store.feed(this).getJSONArray("items");root.addView(strong("Explorar mercados",20));filters(a);if(!category.equals("Todos"))button("Ver todos los hallazgos",()->{category="Todos";visibleLimit=20;home();});root.addView(strong(category.equals("Todos")?"Últimos descubrimientos":category,21));int n=0;for(int i=0;i<a.length();i++){JSONObject item=a.getJSONObject(i);if(!category.equals("Todos")&&!category.equalsIgnoreCase(item.optString("category")))continue;if(n<visibleLimit)finding(item);n++;}if(n>visibleLimit)button("Mostrar más ("+(n-visibleLimit)+")",()->{visibleLimit+=20;home();});if(n==0)section("SIN HALLAZGOS","Conecta la cuenta o actualiza para ver los resultados de esta sección.");}catch(Exception e){label("No se pudo leer el feed.");}}
 void refresh(){if(busy)return;busy=true;message("Sincronizando…");new Thread(()->{try{int n=Store.sync(this);runOnUiThread(()->{busy=false;home();message(n+" nuevos hallazgos");});}catch(Exception e){runOnUiThread(()->{busy=false;message(e.getMessage());});}}).start();}
 void detail(JSONObject o){start(o.optString("name"));button("← Volver",()->home());root.addView(cover(o,224));label(o.optString("category")+" · "+o.optString("country")+" · "+o.optString("date"));section("DESCRIPCIÓN",o.optString("summary","Sin descripción"));section("EVIDENCIA",o.optString("evidence","Sin datos verificados"));section("OPORTUNIDAD",o.optString("opportunity","Pendiente de análisis"));section("RIESGOS",o.optString("risks","Sin evaluación"));section("SIGUIENTE PASO",o.optString("validation","Validar antes de invertir."));JSONArray sources=o.optJSONArray("sources");if(sources!=null)for(int i=0;i<sources.length();i++){String url=sources.optString(i);if(url.startsWith("https://")||url.startsWith("http://"))button("Abrir fuente "+(i+1),()->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){message("No se pudo abrir el enlace");}});}
 button("Analizar oportunidad · calculadora",()->calculator(o));}
 double num(EditText e){try{double n=Double.parseDouble(e.getText().toString());return Double.isFinite(n)&&n>=0?n:0;}catch(Exception x){return 0;}}
 String money(double x){return String.format(Locale.US,"$%,.2f",x);}
 void calculator(JSONObject o){start("Analizar oportunidad");button("← Volver",()->detail(o));label(o.optString("name"));label("Escenario editable en USD. Introduce datos reales; los valores vacíos no son estimaciones.");
 String cat=o.optString("category");boolean equity=cat.equalsIgnoreCase("Empresas")||cat.equalsIgnoreCase("IPO");boolean service=cat.equalsIgnoreCase("Servicios");
 if(equity){EditText buy=input("Precio de compra por acción","",true),target=input("Precio hipotético futuro","",true),shares=input("Cantidad de acciones","",true),fees=input("Comisiones totales","",true);TextView result=text("",16);button("Calcular escenario",()->{double b=num(buy),t=num(target),n=num(shares),f=num(fees);if(b<=0||n<=0||target.getText().toString().trim().isEmpty()){result.setText("Completa precio inicial, precio futuro hipotético y cantidad.");return;}double inv=b*n+f,g=(t-b)*n-f;result.setText("Capital: "+money(inv)+"\nGanancia o pérdida hipotética: "+money(g)+"\nROI: "+String.format(Locale.US,"%.1f%%",g/inv*100)+"\nNo predice el precio futuro.");});root.addView(result);return;}
 EditText purchase=input(service?"Costo variable por cliente":"Compra unitaria","",true),shipping=input(service?"Otros costos variables por cliente":"Transporte unitario","",true),extra=input("Otros costos unitarios","",true),price=input("Precio de venta por "+(service?"cliente":"unidad"),"",true),units=input(service?"Clientes mensuales":"Unidades vendidas","",true),fixed=input(service?"Gastos fijos mensuales":"Gastos fijos del lote","",true),initial=input("Inversión inicial adicional","",true);TextView result=text("",16);
 button("Calcular",()->{double c=num(purchase)+num(shipping)+num(extra),p=num(price),n=num(units),f=num(fixed),inv=num(initial)+c*n+f,g=(p-c)*n-f;if(p<=0||n<=0){result.setText("Completa precio y volumen.");return;}result.setText("Ingresos: "+money(p*n)+"\nCostos operativos: "+money(c*n+f)+"\nUtilidad operativa: "+money(g)+"\nCapital inicial estimado: "+money(inv)+"\nPunto de equilibrio: "+(p>c?String.valueOf((long)Math.ceil(f/(p-c))):"No viable con estos precios")+"\n"+(service&&g>0?"Recuperación aproximada: "+String.format(Locale.US,"%.1f meses",num(initial)/g):"ROI del escenario: "+(inv>0?String.format(Locale.US,"%.1f%%",(g-num(initial))/inv*100):"No calculable"))+"\nAntes de impuestos y costos no ingresados.");});root.addView(result);}
 void settings(){start("Conexión y vigilancia");button("← Volver",()->home());label("Repositorio privado: Vigilante-Sync. Token de acceso fino limitado a ese repositorio, Contents: Read and write. Se cifra en AndroidKeyStore. No compartas el token por chat.");
 EditText token=input("Token nuevo (dejar vacío para conservar)","",false);token.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);
 button("Guardar conexión y sincronizar",()->{try{if(!token.getText().toString().trim().isEmpty()){Store.token(this,token.getText().toString());token.setText("");}home();refresh();}catch(Exception e){message(e.getMessage());}});
 button("Desconectar token",()->{try{Store.token(this,"");message("Desconectado");home();}catch(Exception e){message(e.getMessage());}});
 button("Cargar preferencias desde repositorio",()->{new Thread(()->{try{JSONObject env=Store.http(this,"trendradar-config.json","GET",null);JSONObject conf=Store.decode(env);String sha=env.getString("sha");runOnUiThread(()->editConfig(conf,sha));}catch(Exception e){runOnUiThread(()->message(e.getMessage()));}}).start();});
 label("La investigación se ejecuta mediante el Radar Global de Tendencias de ChatGPT. La app consulta los resultados del repositorio aproximadamente cada 15 minutos si Android y la conexión lo permiten.");}
 void editConfig(JSONObject conf,String sha){start("Preferencias remotas");button("← Volver",()->settings());EditText instructions=input("Prioridades de búsqueda e instrucciones",conf.optString("instructions"),false);instructions.setMinLines(5);button("Guardar cambios en repositorio",()->{String value=instructions.getText().toString();new Thread(()->{try{conf.put("instructions",value);conf.put("updated_at",new java.util.Date().toInstant().toString());Store.saveConfig(this,conf,sha);runOnUiThread(()->{message("Preferencias sincronizadas");settings();});}catch(Exception e){runOnUiThread(()->message(e.getMessage()));}}).start();});}
}
